#!/bin/sh
case "$*" in
  "auth status --hostname github.com") echo "You are not logged into any GitHub hosts." >&2; exit 1;;
  "api --hostname github.com orgs/acme/repos?per_page=100&page=1") cat '<side>/bin/repos.json'; exit 0;;
  "api --hostname github.com repos/acme/widget/git/trees/trunk") cat '<side>/bin/tree-widget.json'; exit 0;;
  "api --hostname github.com repos/acme/api-gateway/git/trees/main") cat '<side>/bin/tree-api.json'; exit 0;;
esac
echo "gh: Server Error (HTTP 502)" >&2
exit 1

