bin/gh.text:
#!/bin/sh
case "$1 $2" in
  "api graphql") cat '<side>/bin/rollup.json'; exit 0;;
esac
case "$*" in
  *"pulls?state=open&head=acme:trunk&per_page=1"*) cat '<side>/bin/pulls.json'; exit 0;;
esac
echo "gh: Server Error (HTTP 502)" >&2
exit 1

