bin/op.text:
#!/bin/sh
# A stand-in for the 1Password CLI. It answers ONLY the exact invocations charter makes,
# argument by argument, and refuses anything else with exit 3 - so a scenario that passes
# pins the argv charter sends. Every value it returns is fabricated for the fixture.
a=""; for x in "$@"; do a="$a[$x]"; done
need_qa() {
  if [ "$OP_SERVICE_ACCOUNT_TOKEN" != "sa-fixture-qa" ]; then
    echo "[ERROR] stub: wrong or missing service-account identity" >&2; exit 4
  fi
}
case "$a" in
  "[item][get][charter-qa][--vault][Fixture QA][--format][json]")
    need_qa
    cat <<'JSON'
{"id":"fixtureitem","title":"charter-qa","category":"PASSWORD","fields":[{"id":"notesPlain","type":"STRING","purpose":"NOTES","label":"notesPlain"},{"id":"KUBE_TOKEN","type":"CONCEALED","label":"KUBE_TOKEN","value":"[concealed]"},{"id":"x7k2","type":"CONCEALED","label":"GITHUB_TOKEN","value":"[concealed]"},{"id":"q9","type":"CONCEALED","label":"","value":"[concealed]"}]}
JSON
    ;;
  "[item][get][charter-qa][--vault][Fixture QA][--format][json][--account][fixture.1password.example]")
    cat <<'JSON'
{"id":"fixtureitem","title":"charter-qa","category":"PASSWORD","fields":[{"id":"KUBE_TOKEN","type":"CONCEALED","label":"KUBE_TOKEN","value":"[concealed]"}]}
JSON
    ;;
  "[read][--no-newline][op://Fixture QA/charter-qa/KUBE_TOKEN]")
    need_qa; printf '%s' 'kube-fixture-0a1b2c3d4e' ;;
  "[read][--no-newline][op://Fixture QA/charter-qa/GITHUB_TOKEN]")
    need_qa; printf '%s\n' 'ghp_fixture_not_a_real_token_000' ;;
  "[read][--no-newline][op://Fixture QA/charter-qa/GONE]")
    need_qa; echo '[ERROR] "GONE" isn'"'"'t a field in the "charter-qa" item' >&2; exit 1 ;;
  "[item][get][charter-fresh][--vault][Fixture QA][--format][json]")
    need_qa; echo '[ERROR] "charter-fresh" isn'"'"'t an item in the "Fixture QA" vault' >&2; exit 1 ;;
  "[item][list][--vault][Fixture QA][--format][json]")
    need_qa; echo '[{"id":"fixtureitem","title":"charter-qa"}]' ;;
  "[item][list][--vault][Fixture QA][--tags][charter:fresh][--format][json]")
    need_qa; echo '[{"id":"olditem","title":"charter-fresh-OLD_KEY"}]' ;;
  "[read][--no-newline][op://Fixture Eng/deploy/token]")
    printf '%s' 'deploy-fixture-token-55aa' ;;
  "[read][--no-newline][op://Fixture Eng/gone/token]")
    echo '[ERROR] could not read secret "op://Fixture Eng/gone/token": deploy-fixture-token-55aa' >&2; exit 1 ;;
  *) echo "stub op: unexpected invocation $a" >&2; exit 3 ;;
esac

